{"implementation":"import math


def _finite_number(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{field} must be a number")
    number = float(value)
    if not math.isfinite(number):
        raise ValueError(f"{field} must be finite")
    return number


def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case requires threshold and calls")

    threshold = _finite_number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise TypeError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for index, call in enumerate(calls):
        if not isinstance(call, dict):
            raise TypeError(f"calls[{index}] must be an object")
        missing = [field for field in required if field not in call]
        if missing:
            raise ValueError(f"calls[{index}] missing required fields: {', '.join(missing)}")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise TypeError(f"calls[{index}].call_id must be a string")

        loss_without = _finite_number(
            call["loss_without_call"], f"calls[{index}].loss_without_call"
        )
        loss_with = _finite_number(
            call["loss_with_call"], f"calls[{index}].loss_with_call"
        )

        prediction_tokens = call["prediction_tokens"]
        if (
            isinstance(prediction_tokens, bool)
            or not isinstance(prediction_tokens, int)
            or prediction_tokens < 0
        ):
            raise ValueError(
                f"calls[{index}].prediction_tokens must be a nonnegative integer"
            )

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise TypeError(f"calls[{index}].parseable must be a boolean")

        normalized_gain = (loss_without - loss_with) / max(1, prediction_tokens)
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append(
            {
                "accepted": accepted,
                "call_id": call_id,
                "normalized_gain": round(normalized_gain, 6),
            }
        )

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
